"use strict";
import { Token } from "@uniswap/sdk-core";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useModalState } from "hooks/useModalState";
import { useMemo } from "react";
import { X } from "react-feather";
import styled from "styled-components";
import { Flex, Separator, Text, useSporeColors } from "ui/src";
import { GoldenVerified, InfoCircleFilled } from "ui/src/components/icons";
import { Modal } from "uniswap/src/components/modals/Modal";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useChainId } from "wagmi";
import { useIncentivizeContext } from "../ContextProvider";
const Button = styled.button`
  all: unset;
  padding: 8px 12px;
  cursor: pointer;
`;
export default function PoolInfoModal() {
  const modalName = ModalName.PoolInfo;
  const { isOpen: isModalOpen, toggleModal: togglePoolInfoModal } = useModalState(modalName);
  const colors = useSporeColors();
  const { selectedPool } = useIncentivizeContext();
  const formatter = useFormatter();
  const chainId = useChainId();
  const onClose = () => {
    togglePoolInfoModal();
  };
  const currencies = useMemo(() => {
    if (!selectedPool?.token0 || !selectedPool?.token1) return [void 0, void 0];
    try {
      const token0 = new Token(
        chainId,
        selectedPool.token0.id,
        parseInt(selectedPool.token0.decimals),
        selectedPool.token0.symbol,
        selectedPool.token0.name
      );
      const token1 = new Token(
        chainId,
        selectedPool.token1.id,
        parseInt(selectedPool.token1.decimals),
        selectedPool.token1.symbol,
        selectedPool.token1.name
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for pool logos:", error);
      return [void 0, void 0];
    }
  }, [selectedPool?.token0, selectedPool?.token1, chainId]);
  const poolName = selectedPool?.token0?.symbol && selectedPool?.token1?.symbol ? `${selectedPool.token0.symbol}/${selectedPool.token1.symbol}` : "WETH/USDC";
  const poolType = selectedPool?.protocol === "V2" ? selectedPool?.type === "Stable" ? "Basic Stable" : "Basic Volatile" : "Concentrated";
  const fee = selectedPool?.protocol === "V2" ? selectedPool?.type === "Stable" ? "0.05%" : "0.3%" : "0.3%";
  const tvl = selectedPool?.reserveUSD || selectedPool?.totalValueLockedUSD || 0;
  const volume = selectedPool?.volumeUSD || 0;
  const infoData = [
    {
      label: "APR",
      value: selectedPool?.protocol === "V2" ? selectedPool?.type === "Stable" ? "0.05%" : "0.3%" : "0.3%"
      // Basic fee rate as APR approximation
    },
    {
      label: "TVL",
      value: tvl ? formatter.formatFiatPrice({ price: tvl, type: NumberType.FiatTokenPrice }) : "N/A"
    },
    {
      label: "Volume",
      value: volume ? formatter.formatFiatPrice({ price: volume, type: NumberType.FiatTokenPrice }) : "N/A"
    },
    {
      label: "Fees",
      value: volume ? formatter.formatFiatPrice({
        price: parseFloat(volume) * (selectedPool?.protocol === "V2" ? selectedPool?.type === "Stable" ? 5e-4 : 3e-3 : 3e-3),
        type: NumberType.FiatTokenPrice
      }) : "N/A"
    },
    {
      label: "Trading fee",
      value: fee
    }
  ];
  return <Modal
    extendOnKeyboardVisible
    fullScreen
    hideKeyboardOnDismiss
    hideKeyboardOnSwipeDown
    renderBehindBottomInset
    backgroundColor={colors.surface1.val}
    isModalOpen={isModalOpen}
    maxWidth={400}
    maxHeight={410}
    name={modalName}
    padding="$none"
    height="100%"
    onClose={onClose}
  >
      <Flex py={"$spacing24"} px={"$spacing20"}>
        <Flex row justifyContent="space-between" alignItems="center">
          <Text variant="subheading2">Pool info</Text>
          <Button onClick={onClose}>
            <Flex
    height={28}
    width={28}
    hoverStyle={{ backgroundColor: colors.surface2Hovered.val }}
    centered
    borderRadius={"$roundedFull"}
  >
              <X color={colors.neutral2Temp.val} size={24} />
            </Flex>
          </Button>
        </Flex>

        <Separator mt={"$spacing8"} width={"100%"} borderColor={"$surface3"} height={1} />

        <Flex group className="info" row gap={"$gap12"} mt={"$spacing24"}>
          <DoubleCurrencyLogo currencies={currencies} size={34} />

          <Flex flexDirection="column" justifyContent="center" gap={"$gap4"}>
            <Flex row gap={"$gap8"} alignItems="center">
              <Text variant="subheading2">{poolName}</Text>
              {selectedPool?.gauge?.id && <GoldenVerified size={"$icon.18"} />}
              <MouseoverTooltip text="Pool Trading Fee" size={TooltipSize.Max} placement="top">
                <Text
    backgroundColor={"$surface3"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant="body4"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
  >
                  {fee}
                </Text>
              </MouseoverTooltip>
              <MouseoverTooltip
    text={<PoolAndGaugeAddress poolAddress={selectedPool?.id} gaugeAddress={selectedPool?.gauge?.id} />}
    size={TooltipSize.Max}
    placement="top"
  >
                <Flex transition="opacity 0.3s ease" opacity={0} $group-hover={{ opacity: 1 }}>
                  <InfoCircleFilled size={"$icon.16"} color={"$neutral2"} />
                </Flex>
              </MouseoverTooltip>
            </Flex>
            <Text variant="body4" fontWeight={"$medium"} color={"$neutral2"}>
              {poolType}
            </Text>
          </Flex>
        </Flex>

        <Flex mt={"$spacing24"}>
          {infoData.map((item, index) => <Flex
    row
    alignItems="center"
    justifyContent="space-between"
    gap={"$gap12"}
    key={index}
    py={"$spacing12"}
    borderTopWidth={1}
    borderColor={index > 0 ? "$surface3" : "transparent"}
  >
              <Text variant="body3" color={"$neutral2"}>
                {item.label}
              </Text>
              <Text variant="body3">{item.value}</Text>
            </Flex>)}
        </Flex>
      </Flex>
    </Modal>;
}
