"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useAvailableGauges } from "hooks/useGaugeData";
import { Contract } from "@ethersproject/contracts";
const BRIBE_ABI = [
  "event NotifyReward(address indexed from, address indexed reward, uint256 indexed epoch, uint256 amount)",
  "function rewardsListLength() external view returns (uint256)",
  "function rewards(uint256 index) external view returns (address)",
  "function tokenRewardsPerEpoch(address token, uint256 epochStart) external view returns (uint256)"
];
const ERC20_ABI = [
  "function symbol() external view returns (string)",
  "function decimals() external view returns (uint8)"
];
export function useUserIncentiveDeposits() {
  const { address, chainId } = useAccount();
  const provider = useEthersProvider();
  const { data: gauges, isLoading: gaugesLoading } = useAvailableGauges();
  const { data: deposits, isLoading } = useQuery({
    queryKey: ["user-incentive-deposits", address, chainId, gauges?.length],
    queryFn: async () => {
      if (!provider || !address || !gauges || gauges.length === 0) return [];
      console.log(`\u{1F50D} [USER INCENTIVES] Fetching deposits for user ${address} across ${gauges.length} gauges`);
      const allDeposits = [];
      for (const gauge of gauges) {
        if (!gauge.bribeContract || gauge.bribeContract === "0x0000000000000000000000000000000000000000") {
          continue;
        }
        try {
          const bribeContract = new Contract(gauge.bribeContract, BRIBE_ABI, provider);
          const currentBlock = await provider.getBlockNumber();
          const fromBlock = Math.max(0, currentBlock - 1e4);
          const filter = bribeContract.filters.NotifyReward(address, null, null);
          const events = await bribeContract.queryFilter(filter, fromBlock, currentBlock);
          console.log(`\u{1F4CB} [USER INCENTIVES] Found ${events.length} deposits for gauge ${gauge.id} (${gauge.pool})`);
          for (const event of events) {
            if (!event.args) continue;
            const [from, reward, epoch, amount] = event.args;
            const block = await provider.getBlock(event.blockNumber);
            let tokenSymbol = "Unknown";
            let tokenDecimals = 18;
            try {
              const tokenContract = new Contract(reward, ERC20_ABI, provider);
              tokenSymbol = await tokenContract.symbol();
              tokenDecimals = await tokenContract.decimals();
            } catch (error) {
              console.warn(`Failed to get token info for ${reward}:`, error);
            }
            allDeposits.push({
              poolId: gauge.pool,
              gaugeId: gauge.id,
              bribeContract: gauge.bribeContract,
              tokenAddress: reward,
              tokenSymbol,
              tokenDecimals,
              amount: amount.toString(),
              epoch: epoch.toString(),
              timestamp: block.timestamp.toString(),
              transactionHash: event.transactionHash,
              blockNumber: event.blockNumber
            });
          }
        } catch (error) {
          console.warn(`Failed to query bribe contract ${gauge.bribeContract} for gauge ${gauge.id}:`, error);
        }
      }
      console.log(`\u2705 [USER INCENTIVES] Found total ${allDeposits.length} user deposits`);
      return allDeposits.sort((a, b) => parseInt(b.timestamp) - parseInt(a.timestamp));
    },
    enabled: !!address && !!provider && !!gauges && !gaugesLoading,
    staleTime: 3e4,
    refetchInterval: 6e4
  });
  const getDepositsByPool = (poolId) => {
    if (!deposits) return [];
    return deposits.filter((deposit) => deposit.poolId.toLowerCase() === poolId.toLowerCase());
  };
  const hasDepositsInPool = (poolId) => {
    return getDepositsByPool(poolId).length > 0;
  };
  const getTotalDepositedInPool = (poolId) => {
    const poolDeposits = getDepositsByPool(poolId);
    return poolDeposits.reduce((sum, deposit) => {
      try {
        const decimals = deposit.tokenDecimals || 18;
        const amount = parseFloat((BigInt(deposit.amount) / BigInt(10 ** decimals)).toString());
        return sum + amount;
      } catch (error) {
        console.warn("Failed to parse deposit amount:", deposit.amount, error);
        return sum;
      }
    }, 0);
  };
  const getDepositSummaryForPool = (poolId) => {
    const poolDeposits = getDepositsByPool(poolId);
    if (poolDeposits.length === 0) return "";
    const tokenSummary = poolDeposits.reduce((acc, deposit) => {
      const symbol = deposit.tokenSymbol || "Unknown";
      if (!acc[symbol]) {
        acc[symbol] = { total: 0, decimals: deposit.tokenDecimals || 18 };
      }
      try {
        const amount = parseFloat((BigInt(deposit.amount) / BigInt(10 ** acc[symbol].decimals)).toString());
        acc[symbol].total += amount;
      } catch (error) {
        console.warn("Failed to parse deposit amount:", deposit.amount, error);
      }
      return acc;
    }, {});
    const summaries = Object.entries(tokenSummary).map(([symbol, data]) => {
      const formatted = data.total >= 1e3 ? `${(data.total / 1e3).toFixed(1)}K` : data.total.toFixed(data.total < 1 ? 4 : 2);
      return `${formatted} ${symbol}`;
    });
    return summaries.join(", ");
  };
  const getDepositTokensForPool = (poolId) => {
    const poolDeposits = getDepositsByPool(poolId);
    if (poolDeposits.length === 0) return [];
    const tokenSummary = poolDeposits.reduce((acc, deposit) => {
      const symbol = deposit.tokenSymbol || "Unknown";
      if (!acc[symbol]) {
        acc[symbol] = {
          total: 0,
          decimals: deposit.tokenDecimals || 18,
          address: deposit.tokenAddress
        };
      }
      try {
        const amount = parseFloat((BigInt(deposit.amount) / BigInt(10 ** acc[symbol].decimals)).toString());
        acc[symbol].total += amount;
      } catch (error) {
        console.warn("Failed to parse deposit amount:", deposit.amount, error);
      }
      return acc;
    }, {});
    return Object.entries(tokenSummary).map(([symbol, data]) => {
      const formatted = data.total >= 1e3 ? `${(data.total / 1e3).toFixed(1)}K` : data.total.toFixed(data.total < 1 ? 4 : 2);
      return {
        symbol,
        amount: formatted,
        address: data.address,
        decimals: data.decimals
      };
    });
  };
  return {
    deposits: deposits || [],
    isLoading: isLoading || gaugesLoading,
    getDepositsByPool,
    hasDepositsInPool,
    getTotalDepositedInPool,
    getDepositSummaryForPool,
    getDepositTokensForPool
  };
}
